cartPage.scss:
$black:  #0f0f0f;
$white:  #ffffff;
$red:  #E82222;
$green: #08BC72;
$grey:  #868686;
$darkgrey: #787878;


.page_type__cart{
    .cart-container{
        .cart-item{
            border-bottom: 0;
        }
        .cart-recommendations{
            border-top: 1px solid $black;
            margin-top: 30px;
            h2{
                text-align: center;
                text-transform: none;
                margin-bottom: 20px;
            }
            h2.page-heading{
                display: none;
            }
            .slick-dots{
                display: block !important;
                margin-bottom: 10px;
                .slick-active{
                    button{
                        color: $green;
                        background-color: $green;
                        border-color: $black;
                    }
                }
                li button{
                    color: $white;
                    background-color: $white;
                    border-color: $black;
                    width: 14px;
                    height: 14px;
                    border-width: 1px;
                    .carousel-tooltip{
                        display: none;
                    }
                }
                li button::before{
                 display: none;
                }
            }
        }
    }
}


@media (min-width: 1300px) {
    .page_type__cart{
        .body {
            .page-heading{
                font-size: 26px;
                text-transform: inherit;
            }
        }
    }
    .cart-container{
        display: flex;
        gap: 40px;
        div[data-cart-content]{
            width: 73.5%;
            .cart{
                //border-bottom: 1px solid $black;
                .cart-header{

                }
                .cart-list{
                    border-top: 0;
                    .cart-item{
                        .cart-item-block.cart-item-figure{

                        }
                        .cart-item-block.cart-item-title{
                            .cart-item-brand{
                                display: none;
                            }
                            .cart-item-name{
                                font-size: 18px;
                            }
                            .product-sku{
                                color: $grey;
                                display: block;
                                margin-top: 4px;
                                margin-bottom: 20px;
                                font-size: 13px;
                            }
                            .definitionList{
                                display: flex;
                                div{
                                    display: flex !important;
                                    flex-direction: row;
                                }
                                .definitionList-key{
                                    font-weight: bold;
                                    color: $black;
                                }
                                .definitionList-value{
                                    margin-right: 26px;
                                }
                            }
                        }
                        .cart-item-block.cart-item-info{
                            vertical-align: top;
                            padding: 1.5rem 0;
                        }
                        .cart-item-block.cart-item-info.cart-item-quantity{
                            padding: 0.6rem 0;
                            vertical-align: top;
                            .form-increment{
                                .button.button--icon{
                                    border: 1px solid $black;
                                    border-radius: 30px;
                                    height: 22px;
                                    padding: 0 14.5px;
                                }
                                .form-input.form-input--incrementTotal.cart-item-qty-input{
                                    border: 0;
                                    font-size: 14px;
                                    font-weight: 300;
                                }
                            }
                        }
                        .cart-item-block.cart-item-info{
                            .prices{
                                display: flex;
                                flex-direction: column;
                                .cart-item-value.price--discounted{
                                    opacity: 0.5;
                                }
                                .cart-item-value{

                                }
                                .cart-item-value.crossed{
                                    text-decoration: line-through;
                                    opacity: 0.5;
                                }
                            }
                        }
                        .cart-item-block.cart-item-info.totalprices{ 
                            display: flex;
                            width: 100%;
                            justify-content: flex-end;
                            padding: 1.5rem 0;
                            .prices{
                                display: flex;
                                flex-direction: column-reverse;
                                .cart-item-value.price--discounted{
                                    opacity: 0.5;
                                }
                                .cart-item-value{

                                }
                                .cart-item-value.crossed{
                                    text-decoration: line-through;
                                    opacity: 0.5;
                                }
                            }
                            .cart-remove{
                                background-color: rgba(255, 255, 255, 0.3);
                                svg{
                                    fill: $black;
                                }
                            }
                        }
                    }
                }
            }
        }
        div[data-cart-totals]{
            width: 26.5%;
            border: 1px solid $black;
            border-radius: 5px;
            margin-bottom: 40px;
            height: max-content;
            .totals-container{
                padding: 24px 30px;
                .summary{
                    margin-top: 0;
                }
                .cart-totals{
                    width: 100% !important;
                    .cart-total{
                        border-top: 0;
                        .cart-total-label{
                            strong{
                                font-weight: 300;
                            }
                            color: $black;
                        }
                    }
                    .cart-total.total{
                        border-top: 1px solid $black;
                        .cart-total-value.cart-total-grandTotal{
                            font-weight: 700;
                        }
                    }
                }
                .cart-actions{
                    .button.button--primary{
                        width: 100%;
                    }
                }
            }
            .coupons-container{
                border-top: 1px solid $black;
                padding: 24px 30px;
                .accordion-block{
                    .accordion-navigation{
                        border: 0;
                        .coupons-accordion-title{
                            margin-top: 0;
                            margin-bottom: 0;
                        }
                        .accordion-navigation-actions{
                            .icon.accordion-indicator {
                                width: 20px;
                            }
                        }
                    }
                    .accordion-navigation.is-open{
                        .accordion-navigation-actions{
                            .toggleLink-text--off {
                                transform: rotate(180deg) !important;
                                transition: transform 0.5s ease;
                            }
                        }
                    }
                    .accordion-content.is-open{
                        padding: 0;
                        .grid-bg{
                            padding-top: 10px;
                            .container{
                                padding: 0;
                            }
                        }
                        .cart-totals{
                            width: 100%;
                            .cart-total{
                                border-top: 0;
                                .cart-total-label{
                                    strong{
                                        font-weight: 300;
                                    }
                                    color: $black;
                                }
                                .cart-form.coupon-code, .cart-form.gift-certificate-code{
                                    margin-bottom: 14px;
                                    .form{
                                        .form-input{
                                            border-left: 0;
                                            border-top: 0;
                                            border-right: 0;
                                        }
                                        .button.button--primary.button--small{
                                            padding-left: 1rem;
                                            padding-right: 1rem;
                                            font-size: 13px;
                                        }
                                    }
                                }
                                .cart-total-value{
                                    .coupon-code-add, .gift-certificate-add{
                                        float: right;
                                        text-align: right;
                                        display: flex;
                                    }
                                }
                            }
                            .cart-total.total{
                                border-top: 1px solid $black;
                                .cart-total-value.cart-total-grandTotal{
                                    font-weight: 700;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

