#CartEditProductFieldsForm{
    .form-field{
        .swatches-wrapper{
            .arrow{
                display: none;
            }
            .swatches-container{
                width: auto;
                max-width: 400px;
                overflow-x: auto;
            }
        }
        .form-label.form-label--alternate.form-label--inlineSmall{
            font-size: 18px;
            text-transform: none;
        }
        .form-option-wrapper{
            padding-left: 10px;
            padding-right: 10px;
            padding-bottom: 4px;
            padding-top: 4px;
            .form-option.form-option-swatch{
                width: 34px;
                height: 34px;
                border-radius: 50%;
            }
            .form-option.form-option-swatch.unavailable{
                .form-option-variant--color{
                    opacity: 0.4;
                }
            }
            .form-option.unavailable + .color-label {
                opacity: 0.4;
            }

            .form-option.unavailable:before{
                visibility: hidden;
            }
            .form-option{
                display: flex;
                border-radius: 10px;
                padding: 7px 0px;
                border: 1px solid $black;
                margin-left: auto;
                margin-right: auto;
            }
            .form-radio:checked + .form-option{
                color: $white;
                background-color: $black;
                font-weight: 700;
                border-color: transparent;
            }
            .color-label{
                text-align: center;
                display: block;
                font-size: 10px;
                max-width: 61px;
                font-weight: 300;
                line-height: 12px;
            }

            /* Styles for a single color swatch */
            .form-option-swatch > .form-option-variant--color:nth-child(1):nth-last-child(1) {
                width: 32px;
                height: 32px;
                border-radius: 50%;
                position: absolute;
                top: 0;
                left: 0;
                border: 0;
            }

            /* Styles when exactly two color swatches are present */
            .form-option-swatch > .form-option-variant--color:nth-child(1):nth-last-child(2),
            .form-option-swatch > .form-option-variant--color:nth-child(2):nth-last-child(1) {
                height: 32px;
                position: absolute;
                top: 0;
                border: 0;
            }

            .form-option-swatch > .form-option-variant--color:nth-child(1):nth-last-child(2) {
                width: 16px;
                border-radius: 32px 0 0 32px;
                left: 0;
            }

            .form-option-swatch > .form-option-variant--color:nth-child(2):nth-last-child(1) {
                width: 16px;
                border-radius: 0 32px 32px 0;
                left: 16px;
            }

            /* Styles when exactly three color swatches are present */
            .form-option-swatch > .form-option-variant--color:nth-child(1):nth-last-child(3),
            .form-option-swatch > .form-option-variant--color:nth-child(2):nth-last-child(2),
            .form-option-swatch > .form-option-variant--color:nth-child(3):nth-last-child(1) {
                height: 32px;
                position: absolute;
                top: 0;
                border: 0;
            }

            .form-option-swatch > .form-option-variant--color:nth-child(1):nth-last-child(3) {
                width: 16px;
                border-radius: 32px 0 0 32px;
                left: 0;
            }

            .form-option-swatch > .form-option-variant--color:nth-child(2):nth-last-child(2) {
                width: 10px;
                left: 11px;
                z-index: 2;
                border-radius: 4px;
            }

            .form-option-swatch > .form-option-variant--color:nth-child(3):nth-last-child(1) {
                width: 15px;
                border-radius: 0 32px 32px 0;
                left: 16px;
            }
        }
        .productOptions-list{
            border-radius: 10px;
        }
    }
    .form-actions{
        .button.button--primary{
            border-radius: 30px;
            text-transform: none;
        }
    }
}

@media (min-width: 800px) {
