                    position: relative;
                    .cart-remove.icon{
                        position: absolute;
                        right: 0;
                        background-color: unset;
                    }
                    .cart-item-name{
                        width: 90%;
                    }
                }
                .cart-item-block.cart-item-info.totalprices{
                    .cart-remove.icon{
                        visibility: hidden;
                    }
                }
                .cart-item-block.cart-item-info.cart-item-quantity{
                    text-align: center;
                    .form-label.cart-item-label{
                        display: none;
                    }
                }
            }
        }
    }
}
